if (!V8.Param.TableId) {
  return { Code: 0, Msg: '参数错误！' };
}
//判断新表名是否已存在
if (V8.Param.TableName) {
  var newTableModelResult = V8.FormEngine.GetFormData('Diy_Table', {
    _Where: [
      ['Name', '=', V8.Param.TableName]
    ]
  });
  if (newTableModelResult.Code == 1 && newTableModelResult.Data) {
    return { Code: 0, Msg: `新的表名【${V8.Param.TableName}】已存在！` };
  }
}
//取原表
var oldTableModelResult = V8.FormEngine.GetFormData('Diy_Table', {
  Id: V8.Param.TableId
});
if (oldTableModelResult.Code != 1) {
  return oldTableModelResult;
}
var oldTableModel = oldTableModelResult.Data;
//取原表大概存在多少个复制体
var oldTableListResult = V8.FormEngine.GetTableData('Diy_Table', {
  _Where: [
    ['Name', 'StartLike', oldTableModel.Name]
  ]
});
if (oldTableListResult.Code != 1) {
  return oldTableListResult;
}
var oldTableNewCount = oldTableListResult.Data.length + 1;

//取原表所有字段
var oldTableFieldListResult = V8.FormEngine.GetTableData('Diy_Field', {
  _Where: [
    ['TableId', '=', V8.Param.TableId]
  ],
});
if (oldTableFieldListResult.Code != 1) {
  return oldTableFieldListResult;
}
var oldTableFieldList = oldTableFieldListResult.Data;
//插入新表
var newTableModel = { ...oldTableModel };
//定义新的TableId，后面插入字段需要用到
var newTableId = V8.Method.NewUlid();
newTableModel.Id = newTableId;
newTableModel.Name = V8.Param.TableName || (newTableModel.Name + oldTableNewCount);
newTableModel.Description = V8.Param.Description || newTableModel.Name;
var addTableResult = V8.FormEngine.AddTable(newTableModel, V8.DbTrans);//带事务
if (addTableResult.Code != 1) {
  return { Code: 0, Msg: '插入新表失败：' + addTableResult.Msg }//addTableResult;
}

//插入新表字段（跳过审计字段，AddTable已自动创建）
var fixedFieldNames = ['Id', 'CreateTime', 'UpdateTime', 'UserId', 'UserName', 'IsDeleted'];
for (var i = 0; i < oldTableFieldList.length; i++) {
  var oldField = oldTableFieldList[i];
  //跳过审计字段（IsLockField==1 或 字段名在固定字段列表中），AddTable已自动创建
  if (oldField.IsLockField == 1 || fixedFieldNames.indexOf(oldField.Name) > -1) {
    continue;
  }
  var newFieldModel = { ...oldField };
  //删除Id，防止重复
  delete newFieldModel.Id;
  newFieldModel.TableId = newTableId;
  newFieldModel.TableName = newTableModel.Name;
  var addFieldResult = V8.FormEngine.AddField(newFieldModel, V8.DbTrans);//带事务
  if (addFieldResult.Code != 1) {
    return { Code: 0, Msg: `插入字段[${newFieldModel.Name}]失败：` + addFieldResult.Msg }; //addFieldResult;
  }
}
V8.Result = { Code: 1 };
